import numpy as np
import scipy.linalg


class Solver:
    def solve(self, problem, **kwargs):
        A = np.asarray(problem["matrix"], dtype=complex)
        n = A.shape[0]

        # Denman-Beavers iteration for the principal matrix square root.
        # Y -> sqrt(A), Z -> inv(sqrt(A)); converges quadratically.
        Y = A.copy()
        Z = np.eye(n, dtype=complex)
        for _ in range(40):
            Yi = np.linalg.inv(Y)
            Zi = np.linalg.inv(Z)
            Y = 0.5 * (Y + Zi)
            Z = 0.5 * (Z + Yi)
            if np.max(np.abs(Y @ Y - A)) < 1e-8:
                break
        else:
            # Fallback to the reference implementation if iteration stalls.
            X, _ = scipy.linalg.sqrtm(A, disp=False)
            return {"sqrtm": {"X": X.tolist()}}

        return {"sqrtm": {"X": Y.tolist()}}

